(async () => {
  const mode = args[0];
  console.log("信仰守卫 Macro.Execute triggered, mode:", mode);

  if (mode !== "on") return;

  const last = args.at(-1);
  const targetToken = canvas.tokens.get(last.tokenId);
  const targetActor = targetToken?.actor;
  if (!targetActor) {
    return console.warn("No target actor found");
  }

  const casterDoc = await fromUuid(last.origin);
  const caster = casterDoc?.actor || casterDoc;
  const casterToken = caster?.getActiveTokens?.()[0];
  const saveDC = getProperty(caster, "system.attributes.spell.dc");

  const save = await targetActor.rollAbilitySave("dex", {
    flavor: `DEX Save vs 信仰守卫 DC ${saveDC}`
  });

  const damage = (save.total >= saveDC ? 10 : 20);
  console.log(`Applying radiant damage: ${damage}`);
  const roll = await new Roll(`${damage}`).roll({ async: true });
  await game.dice3d?.showForRoll(roll);

  await new MidiQOL.DamageOnlyWorkflow(
    caster,
    casterToken,
    damage,
    "radiant",
    [targetToken],
    roll,
    {
      flavor: `${damage} radiant damage from Faith Guard`,
      itemCardId: "new",
      isCritical: false
    }
  );

  // 清除 Aura 效果以防重复触发
  const aura = targetActor.effects.find(e => e.origin === last.origin);
  if (aura) {
    await aura.delete();
    console.log("🧹 Removed Faith Guard aura from actor");
  } else {
    console.log("⚠️ Aura effect not found on actor for removal");
  }
})();
